import {STORAGE_KEY,emptyProgress,validateProgress,filterRoutes,summary,contributionUrl,navigationLegs,googleMapsUrl,routeGpx} from './domain.mjs';
import {mountMap} from './map.mjs';

const paths={route:'M4 19V9a4 4 0 0 1 4-4h11m-4-4 4 4-4 4',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',book:'M5 3h14v18l-7-4-7 4z',pin:'M20 10c0 6-8 11-8 11S4 16 4 10a8 8 0 1 1 16 0zM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',arrow:'M5 12h14m-6-6 6 6-6 6',external:'M14 3h7v7m0-7L10 14M10 3H3v18h18v-7',search:'M21 21l-6-6m2-6a7 7 0 1 1-14 0 7 7 0 0 1 14 0',check:'m5 12 4 4L19 6',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',plus:'M12 5v14M5 12h14',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M13 3a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.87M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',shield:'m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6z',close:'m6 6 12 12M6 18 18 6',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',road:'m7 2-4 20M17 2l4 20M12 2v4m0 4v4m0 4v4',info:'M12 11v6m0-11v1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.route}"/></svg>`;
const e=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const highway='https://www.gov.uk/guidance/the-highway-code/using-the-road-159-to-203';
const scenarios=[
 {id:'d-junction',title:'The D junction',place:'Plains Avenue / Marion Crescent',tag:'Local knowledge',icon:'route',text:'A distinctive junction layout to discuss with your instructor before visiting.',checks:['Identify each approach and the current signs and markings.','Discuss how to choose a safe position with your instructor.','Look carefully for pedestrians, cyclists and vehicles at each conflict point.'],source:'https://maidstonetestroutes.com/d-junction/',note:'The linked local article is historical. Current layout and priorities need on-site confirmation; do not rely on its diagrams for priority.'},
 {id:'running-horse',title:'Running Horse roundabout',place:'North Maidstone',tag:'Lane planning',icon:'road',text:'Practise reading destination signs early and planning a safe approach.',checks:['Agree an intended destination before the approach.','Follow current signs and lane markings.','Discuss a safe alternative if the intended exit is missed.'],source:'https://maidstonetestroutes.com/running-horse-roundabout/',note:'Lane arrangements may have changed. No lane-specific instruction is supplied by this app.'},
 {id:'mini-roundabouts',title:'Mini roundabouts',place:'A skill for every route',tag:'Roundabouts',icon:'route',text:'Build a calm routine for observation, appropriate speed and positioning.',checks:['Identify the junction and assess traffic early.','Look for vulnerable road users as well as vehicles.','Review your observations and decisions after parking.'],source:highway},
 {id:'meeting-traffic',title:'Meeting on narrow roads',place:'Residential streets',tag:'Meeting traffic',icon:'people',text:'Look ahead for parked vehicles, passing places and developing hazards.',checks:['Discuss how parked vehicles affect your view.','Plan where to wait without blocking a junction.','Leave appropriate space around people and vehicles.'],source:highway},
 {id:'junctions',title:'Junction observations',place:'Town and residential roads',tag:'Junctions',icon:'search',text:'Work on taking enough time to understand the whole junction.',checks:['Spot signs, road markings and restricted visibility.','Discuss pedestrians crossing or waiting to cross.','Review any emerging decision that felt rushed.'],source:highway},
 {id:'independent',title:'Independent driving',place:'Build transferable confidence',tag:'Observation',icon:'pin',text:'Practise following a planned destination without rushing decisions.',checks:['Agree a suitable route with your supervisor while parked.','Follow signs and current restrictions rather than a memorised route.','Choose a safe alternative instead of making a late manoeuvre.'],source:highway}
];

let routes=[],centres=[],progress=emptyProgress(),storageBlocked=false,tab='routes',selected='maidstone-01',query='',skill='',savedOnly=false;
let cleanupMap=()=>{};
const app=document.querySelector('#app');
const toast=message=>{document.querySelector('#toast').textContent=message;document.querySelector('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>document.querySelector('#toast').classList.remove('show'),4000);};
function persist(){if(storageBlocked){toast('Changes are in memory only. Export a backup before leaving.');return;}try{localStorage.setItem(STORAGE_KEY,JSON.stringify(progress));}catch{storageBlocked=true;toast('Browser storage unavailable. Export your progress to keep it.');render();}}
function routeById(id){return routes.find(r=>r.id===id);}
function recent(id){return progress.sessions.filter(s=>s.routeId===id).sort((a,b)=>b.date.localeCompare(a.date))[0];}
function nav(id,label,glyph){return `<button class="nav-item ${tab===id?'active':''}" data-tab="${id}" ${tab===id?'aria-current="page"':''}>${icon(glyph)}<span>${label}</span>${id==='routes'?'<span class="count">10</span>':''}</button>`;}
function render(){
 cleanupMap();
 const stats=summary(progress);
 app.innerHTML=`<aside class="sidebar"><a class="brand" href="#">${icon('route')}<span>routewise<span class="brand-dot">.</span></span></a><div class="workspace-label">YOUR DRIVING COMPANION</div><nav aria-label="Main navigation">${nav('routes','Explore routes','grid')}${nav('scenarios','Driving scenarios','road')}${nav('log','My practice','book')}${nav('community','Community','people')}</nav><div class="sidebar-bottom"><div class="open-source">${icon('heart')}<b>Better, together.</b><p>Built in the open.<br>Made for every learner.</p><a href="https://github.com/yesoreyeram/driving" target="_blank" rel="noopener noreferrer">Explore on GitHub ${icon('external')}</a></div><div class="local-status">${icon('shield')} Your progress stays on this device</div></div></aside>
 <div class="page"><header class="topbar"><div class="breadcrumb">Your journey <span>/</span> <b>${({routes:'Explore routes',scenarios:'Driving scenarios',log:'My practice',community:'Community'})[tab]}</b></div><div class="top-actions"><span class="beta">EARLY ACCESS</span><button class="location" data-action="centre">${icon('pin')} Maidstone, Kent ${icon('info')}</button></div></header>
 <main id="main"><div class="page-heading"><div><div class="eyebrow">A LITTLE FAMILIARITY GOES A LONG WAY</div><h1>${({routes:'Your next confident drive.',scenarios:'Prepare for the tricky bits.',log:'Every drive is progress.',community:'Local knowledge. Shared.'})[tab]}</h1><p>${({routes:'Explore local roads. Practise real skills. Feel more at home behind the wheel.',scenarios:'Go beyond memorising routes. Build skills you can take to any road.',log:'Reflect while parked, spot patterns and choose what to practise next.',community:'Help make driving practice more accessible, one reviewed contribution at a time.'})[tab]}</p></div>${tab==='routes'?`<button class="button secondary" data-tab="log">${icon('book')} My practice log ${icon('arrow')}</button>`:''}</div>
 ${storageBlocked?'<div class="notice error">Browser storage could not be read or saved. Changes are in memory only; export before leaving. Existing stored data has been left untouched.</div>':''}
 ${tab==='routes'?routePage(stats):tab==='scenarios'?scenarioPage():tab==='log'?logPage(stats):communityPage()}
 <footer><span>Learn the roads. Keep the skills.</span><div><a href="https://github.com/yesoreyeram/driving" target="_blank" rel="noopener noreferrer">Open source ${icon('external')}</a><button data-tab="community">About & sources</button></div></footer></main></div>`;
 wire();
}
function routePage(stats){
 return `<section class="hero"><div class="hero-content"><span class="hero-label"><span class="live-dot"></span> STARTING IN MAIDSTONE</span><h2>Familiar roads.<br>Fresh confidence.</h2><p>A little preparation makes a big difference.<br>Find a route, pick a focus, and make your next drive count.</p><button class="button light" data-action="find-focus">Find my practice focus ${icon('arrow')}</button></div><div class="hero-art" aria-hidden="true"><svg viewBox="0 0 500 260"><path class="contour" d="M130-40C-90 50 100 340 300 220S620 150 500-30M170-10C-30 60 120 300 300 190S580 150 470-10M210 20C40 80 150 255 300 160S530 130 440 20"/><path class="route-shadow" d="M130 225V145q0-35 35-35h105q35 0 35-35V45"/><path class="route-line" d="M130 225V145q0-35 35-35h105q35 0 35-35V45"/><circle cx="130" cy="224" r="13" fill="#dcebb9"/><circle cx="130" cy="224" r="5" fill="#214c3e"/><circle cx="305" cy="44" r="24" fill="#dcebb9"/><path d="m296 44 6 6 12-13" stroke="#214c3e" stroke-width="4" fill="none"/><g transform="translate(200 97)"><rect width="58" height="28" rx="8" fill="#fff"/><rect x="8" y="5" width="17" height="18" rx="3" fill="#214c3e"/><rect x="33" y="5" width="17" height="18" rx="3" fill="#214c3e"/></g></svg><div class="art-caption">ONE DRIVE AT A TIME</div></div></section>
 <section class="stats" aria-label="Practice overview"><div>${icon('route')}<span><strong>${routes.length}</strong> local practice routes</span><span class="stat-note">A starting point to explore</span></div><div>${icon('road')}<span><strong>${scenarios.length}</strong> driving scenarios</span><span class="stat-note">Real skills, beyond routes</span></div><div>${icon('check')}<span><strong>${stats.routes} / ${routes.length}</strong> routes practised</span><span class="stat-note">${stats.sessions?'Keep your momentum going':'Your journey starts here'}</span></div></section>
 <div class="section-heading"><div><h2>Explore Maidstone <span class="pill neutral">Kent</span></h2><p>Pick a route to get to know the roads.</p></div><label class="toggle"><input id="saved-only" type="checkbox" ${savedOnly?'checked':''}> Saved routes</label></div>
 <div class="explorer"><section class="route-browser" aria-label="Route browser"><div class="filter-row"><label class="search">${icon('search')}<input id="route-search" type="search" placeholder="Search roads or routes…" value="${e(query)}" aria-label="Search roads or routes"></label><select id="skill-filter" aria-label="Filter by practice focus"><option value="">All skills</option>${[...new Set(routes.flatMap(r=>r.skills))].sort().map(s=>`<option ${s===skill?'selected':''}>${e(s)}</option>`).join('')}</select></div><div class="results-meta"><span id="result-count"></span><span>Source-linked · unverified</span></div><div id="route-list" class="route-list"></div></section><section id="route-detail" class="detail" aria-label="Selected route"></section></div>
 <div class="safety-strip">${icon('shield')}<div><strong>Plan while parked. Practise with support.</strong><p>Practice routes are not official DVSA routes. Use a qualified instructor or eligible supervisor, follow current road signs and never interact with this app while driving.</p></div><a href="https://www.gov.uk/driving-lessons-learning-to-drive" target="_blank" rel="noopener noreferrer">Learner guidance ${icon('external')}</a></div>`;
}
function renderRouteList(){
 const list=filterRoutes(routes,{query,skill,savedOnly,bookmarks:progress.bookmarks});
 document.querySelector('#result-count').textContent=`${list.length} ${list.length===1?'route':'routes'} found`;
 document.querySelector('#route-list').innerHTML=list.length?list.map(r=>{const last=recent(r.id);return `<article class="route-card ${selected===r.id?'selected':''}"><button class="route-select" data-select="${r.id}" aria-pressed="${selected===r.id}"><span class="route-number">${String(r.number).padStart(2,'0')}</span><div><div class="card-kicker">MAIDSTONE · ROUTE ${String(r.number).padStart(2,'0')}</div><h3>${e(r.title)}</h3><p>${e(r.summary)}</p><div class="tags">${r.skills.map(s=>`<span>${e(s)}</span>`).join('')}</div>${last?`<span class="practised">${icon('check')} Practised · confidence ${last.confidence}/5</span>`:''}</div></button><button class="bookmark ${progress.bookmarks.includes(r.id)?'is-saved':''}" data-save="${r.id}" aria-label="${progress.bookmarks.includes(r.id)?'Unsave':'Save'} ${e(r.title)}" aria-pressed="${progress.bookmarks.includes(r.id)}">${icon('book')}</button></article>`;}).join(''):`<div class="empty">${icon('search')}<h3>No routes found</h3><p>Try another road, clear the skill filter or show all routes.</p><button class="button secondary" data-action="reset-filters">Reset filters</button></div>`;
 document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{selected=b.dataset.select;renderRouteList();renderDetail();});
 document.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>{const id=b.dataset.save;progress.bookmarks=progress.bookmarks.includes(id)?progress.bookmarks.filter(x=>x!==id):[...progress.bookmarks,id];persist();renderRouteList();});
 document.querySelector('[data-action="reset-filters"]')?.addEventListener('click',()=>{query='';skill='';savedOnly=false;render();});
}
function renderDetail(){
 cleanupMap();
 const r=routeById(selected),n=progress.sessions.filter(s=>s.routeId===r.id).length;
 document.querySelector('#route-detail').innerHTML=`<div class="detail-heading"><div><span class="card-kicker">GET TO KNOW THE AREA</span><h3>${e(r.title)}</h3></div><span class="pill amber">Needs verification</span></div><div class="map" id="route-map" role="region" aria-label="Historical source route maps"></div><div class="detail-body"><div class="detail-meta"><span>${icon('pin')} Armstrong Road area</span><span>${icon('book')} ${n?n+' practice '+(n===1?'session':'sessions'):'Not practised yet'}</span></div><h4>Roads to get familiar with</h4><div class="road-chips">${r.roads.map(road=>`<a href="https://www.openstreetmap.org/search?${new URLSearchParams({query:road+', Maidstone, Kent'})}" target="_blank" rel="noopener noreferrer">${e(road)} ${icon('external')}</a>`).join('')}</div><p class="small muted">Road highlights, not complete directions. Open the original source for its route maps. Current access and layout have not been checked.</p><div class="focus-box"><span class="focus-icon">${icon('road')}</span><div><strong>Make this drive about ${e(r.skills[0].toLowerCase())}.</strong><p>Suggested learning focus. Agree a suitable plan with your instructor or supervisor.</p></div></div>${navigationPanel(r)}<div class="detail-buttons"><button class="button primary" data-action="practice">${icon('plus')} Plan & log practice</button><a class="button secondary" href="${e(r.source.url)}" target="_blank" rel="noopener noreferrer">Source & maps ${icon('external')}</a></div><div class="source-line">Source: Maidstone Test Routes · accessed 26 Oct 2026<br>On-road verification: pending · geometry: not supplied</div><button class="text-button" data-action="report">Report an issue with this route ${icon('arrow')}</button></div>`;
 cleanupMap=mountMap(document.querySelector('#route-map'),r.navigation.sourceMaps);
 document.querySelector('[data-action="practice"]').onclick=()=>practiceDialog(r.id);
 document.querySelector('[data-action="full-route"]').onclick=()=>navigationDialog(r);
 document.querySelector('[data-action="report"]').onclick=()=>{tab='community';render();document.querySelector('#kind').value='Route correction';document.querySelector('#proposal-title').value=r.title;document.querySelector('#proposal-roads').value=r.roads.join(', ');};
}
function scenarioPage(){return `<div class="notice">${icon('info')} <span>Preparation prompts, not live manoeuvre instructions. Review local layouts with an instructor and follow the current Highway Code.</span></div><div class="scenario-grid">${scenarios.map((s,i)=>`<article class="scenario-card"><div class="scenario-art art-${i}">${icon(s.icon)}<span>0${i+1}</span></div><div class="scenario-content"><span class="pill neutral">${e(s.tag)}</span><h2>${e(s.title)}</h2><span class="muted small">${e(s.place)}</span><p>${e(s.text)}</p><button class="text-button" data-scenario="${s.id}">${progress.scenarioChecks.includes(s.id)?icon('check')+' Reviewed · revisit':'Explore scenario '+icon('arrow')}</button></div></article>`).join('')}</div>`;}
function logPage(stats){return `<section class="log-stats"><div><strong>${stats.sessions}</strong><span>practice sessions</span></div><div><strong>${stats.minutes}</strong><span>minutes behind the wheel</span></div><div><strong>${stats.routes}</strong><span>different routes explored</span></div><div><strong>${progress.scenarioChecks.length}</strong><span>scenarios reviewed</span></div></section><div class="section-heading"><div><h2>Your practice journal</h2><p>Private to this browser. Export a backup to keep your progress.</p></div><div class="button-group"><button class="button secondary" data-action="export">${icon('download')} Export</button><button class="button secondary" data-action="import">Import</button><button class="button primary" data-action="new-log">${icon('plus')} Log practice</button><input type="file" id="import-file" accept="application/json,.json" hidden></div></div>${progress.sessions.length?`<div class="journal">${[...progress.sessions].sort((a,b)=>b.date.localeCompare(a.date)).map(s=>`<article class="journal-entry"><div class="journal-date">${e(new Date(s.date+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}))}</div><div><h3>${e(routeById(s.routeId).title)}</h3><span class="pill neutral">${s.minutes} min</span> <span class="pill green">Confidence ${s.confidence}/5</span><p class="notes">${e(s.notes||'No notes added.')}</p></div><button class="text-button danger" data-delete="${e(s.id)}">Delete</button></article>`).join('')}</div>`:`<div class="empty log-empty">${icon('route')}<h2>Your first drive is a fresh start.</h2><p>After a practice drive, record what went well and what to work on next.</p><button class="button primary" data-action="new-log">Log your first practice ${icon('arrow')}</button></div>`}<div class="notice">${icon('shield')} No account, analytics or location recording. The external Google map preview receives normal map requests. Your browser may clear local data; keep an exported backup. Confidence is self-reported, not a measure of test readiness.</div>`;}
function communityPage(){return `<div class="community-layout"><section class="panel"><span class="eyebrow">BUILT IN THE OPEN</span><h2>A better map starts with you.</h2><p>Know a road that's changed? Have an original route to share? Propose an update for review.</p><form id="contribution-form"><label>Contribution type<select id="kind"><option>New practice route</option><option>Route correction</option><option>Driving scenario</option><option>New test centre</option></select></label><label>Short title<input id="proposal-title" required maxlength="100" placeholder="e.g. Updated signs on Plains Avenue"></label><label>Location / roads<input id="proposal-roads" required maxlength="250" placeholder="Roads and test centre"></label><label>What should we know?<textarea id="proposal-notes" required minlength="20" maxlength="1500" rows="4" placeholder="Describe the change, when you observed it and what needs review."></textarea></label><label>Evidence & permission<textarea id="proposal-evidence" required maxlength="600" rows="2" placeholder="Source URL, observation date, and confirmation you can share this material."></textarea></label><label class="check-label"><input type="checkbox" required> This is my own contribution or I have permission to share it. I have not included personal data.</label><button type="submit" class="button primary">Prepare GitHub proposal ${icon('arrow')}</button><p class="small muted">Opens a pre-filled GitHub issue for you to review and submit. Nothing is sent automatically. A GitHub account is required.</p></form></section><aside class="community-aside"><section class="panel"><span class="pill green">MVP · MAIDSTONE FIRST</span><h3>Open source. Human reviewed.</h3><ol class="review-flow"><li><b>Propose</b><span>Add context, evidence and permission.</span></li><li><b>Review</b><span>A maintainer checks provenance, legality and safety.</span></li><li><b>Verify on the road</b><span>An independent reviewer confirms the current layout.</span></li><li><b>Publish transparently</b><span>Keep verification dates and sources visible.</span></li></ol><a class="button secondary" href="https://github.com/yesoreyeram/driving" target="_blank" rel="noopener noreferrer">View the project ${icon('external')}</a></section><section class="panel"><h3>About the route data</h3><p>Ten route references are based on factual road names from <a href="https://maidstonetestroutes.com/amp/" target="_blank" rel="noopener noreferrer">Maidstone Test Routes</a>, accessed 26 October 2026. Original articles and maps remain with their publisher.</p><p>These are historical, source-linked practice ideas. None has been independently verified by this project. They are not official DVSA routes or guaranteed test routes.</p><p>Practice skill tags are our suggested learning focuses, not verified road attributes. Distances, travel times, road-following geometry and lane instructions are absent until verified. Source map coordinates are provided as an ordered GPX route plan, which your navigation app recalculates.</p><a href="https://www.gov.uk/driving-lessons-learning-to-drive/practising-with-family-or-friends" target="_blank" rel="noopener noreferrer">Check private practice requirements ${icon('external')}</a></section></aside></div>`;}
function practiceDialog(id){
 const r=routeById(id);const dialog=document.querySelector('#practice-dialog');
 dialog.innerHTML=`<div class="modal-heading"><div><span class="eyebrow">PLAN BEFORE. REFLECT AFTER.</span><h2 id="practice-title">Make your next drive count.</h2></div><button class="icon-button" data-close aria-label="Close practice dialog">${icon('close')}</button></div><form id="practice-form"><label>Practice route<select name="routeId">${routes.map(x=>`<option value="${x.id}" ${x.id===id?'selected':''}>${e(x.title)}</option>`).join('')}</select></label><div class="mini-plan"><strong>Before you go</strong><p>Agree a route and skill focus with your instructor or eligible supervisor. Check current signs, insurance and learner requirements. Park safely before using the app.</p><a href="${e(r.source.url)}" id="plan-source" target="_blank" rel="noopener noreferrer">Review original route maps ${icon('external')}</a></div><h3>After your drive</h3><div class="form-row"><label>Practice date<input name="date" type="date" required value="${localDate()}" max="${localDate()}"></label><label>Duration (minutes)<input name="minutes" type="number" min="1" max="480" required value="30"></label></div><fieldset><legend>How confident did you feel?</legend><div class="rating">${[1,2,3,4,5].map(i=>`<label><input type="radio" name="confidence" value="${i}" ${i===3?'checked':''}><span>${i}</span></label>`).join('')}</div><div class="rating-labels"><span>Needed support</span><span>Felt comfortable</span></div></fieldset><label>What went well? What next?<textarea name="notes" rows="3" maxlength="2000" placeholder="e.g. Better observations today. Practise lane planning next time."></textarea></label><label class="check-label"><input type="checkbox" required> The drive is complete and I am safely parked.</label><button type="submit" class="button primary full">${icon('check')} Save practice session</button></form>`;
 dialog.querySelector('[data-close]').onclick=()=>dialog.close();
 dialog.querySelector('[name="routeId"]').onchange=ev=>dialog.querySelector('#plan-source').href=routeById(ev.target.value).source.url;
 dialog.querySelector('form').onsubmit=ev=>{ev.preventDefault();const f=new FormData(ev.target);const session={id:(crypto.randomUUID?.() || Array.from(crypto.getRandomValues(new Uint8Array(16)),v=>v.toString(16).padStart(2,'0')).join('')),routeId:f.get('routeId'),date:f.get('date'),minutes:Number(f.get('minutes')),confidence:Number(f.get('confidence')),notes:f.get('notes').trim()};if(session.date>localDate()){toast('Practice date cannot be in the future.');return;}try{progress=validateProgress({...progress,sessions:[...progress.sessions,session]},routes.map(r=>r.id));persist();dialog.close();render();toast(storageBlocked?'Session kept in memory. Export to retain it.':'Practice saved. Every drive is progress.');}catch(err){toast(err.message);}};
 dialog.showModal();
}
function localDate(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function navigationPanel(r){const legs=navigationLegs(r.navigation.waypoints);return `<section class="nav-panel"><h4>${icon('route')} Take the route with you</h4><p>One full-route GPX plan · ${r.navigation.waypoints.length} ordered source points · no Google stop limit</p><div class="nav-options"><button class="button primary" data-action="full-route">${icon('download')} Full route for navigation</button><a class="button secondary" href="${e(googleMapsUrl(legs[0]))}" target="_blank" rel="noopener noreferrer">Google Maps · leg 1 ${icon('external')}</a></div><details><summary>All ${legs.length} Google Maps legs & route points</summary><p>Google Maps has a waypoint limit, so this fallback uses linked legs. Stop safely before opening the next leg. Navigation apps recalculate between points; review the path first.</p><div class="nav-legs">${legs.map((leg,i)=>`<a href="${e(googleMapsUrl(leg))}" target="_blank" rel="noopener noreferrer"><span>Leg ${i+1} of ${legs.length} · ${leg.length-2} intermediate points</span>${icon('external')}</a>`).join('')}</div><ol class="waypoint-list">${r.navigation.waypoints.map(p=>`<li>${e(p.label)}</li>`).join('')}</ol></details><p>Historical source points, not a verified road trace. Check the route against current restrictions with your instructor.</p></section>`;}
function saveGpx(r){const blob=new Blob([routeGpx(r)],{type:'application/gpx+xml'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`routewise-${r.id}.gpx`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);}
function navigationDialog(r){
 const d=document.querySelector('#navigation-dialog');
 d.innerHTML=`<div class="modal-heading"><div><span class="eyebrow">THE WHOLE PLAN. ONE FILE.</span><h2 id="navigation-title">Practise beyond the stop limit.</h2></div><button class="icon-button" data-close aria-label="Close navigation instructions">${icon('close')}</button></div><p><b>${e(r.title)}</b> · ${r.navigation.waypoints.length} ordered points.</p><div class="notice">This is a GPX route plan, not a verified road-following track. Your navigation app calculates roads between the source points. It may differ from the article’s road-by-road description.</div><ol class="gpx-instructions"><li><b>Download the full GPX plan</b> below, or share the file to a compatible app.</li><li><b>Open or import it in OsmAnd.</b> Download the local map and choose the car profile. Keep the source point order.</li><li><b>Review the calculated route while parked.</b> Check current restrictions, safe stopping places and road access with your instructor. Do not use straight-line routing.</li><li><b>Start navigation from the beginning.</b> In OsmAnd, choose the imported route and Navigate / Follow track. Controls vary by app version.</li></ol><div class="nav-options"><button class="button primary" id="download-gpx">${icon('download')} Download full GPX</button><button class="button secondary" id="share-gpx">${icon('external')} Share route file</button></div><p><a href="https://osmand.net/docs/user/navigation/setup/gpx-navigation/" target="_blank" rel="noopener noreferrer">OsmAnd GPX navigation guide ${icon('external')}</a></p><p class="small muted">Google Maps, Apple Maps and Waze are not offered as full-GPX import targets. Google Maps legs remain available as a fallback. App handoff depends on the installed apps and device.</p>`;
 d.querySelector('[data-close]').onclick=()=>d.close();d.querySelector('#download-gpx').onclick=()=>saveGpx(r);
 d.querySelector('#share-gpx').onclick=async()=>{const file=new File([routeGpx(r)],`routewise-${r.id}.gpx`,{type:'application/gpx+xml'});if(navigator.canShare?.({files:[file]})){try{await navigator.share({files:[file],title:r.title});}catch(err){if(err.name!=='AbortError')toast('Sharing unavailable. Download and import the GPX file instead.');}}else{saveGpx(r);toast('File sharing is not supported here. Import the downloaded GPX in your navigation app.');}};
 d.showModal();
}
function scenarioDialog(id){const s=scenarios.find(s=>s.id===id),d=document.querySelector('#scenario-dialog');d.innerHTML=`<div class="modal-heading"><div><span class="eyebrow">${e(s.place)}</span><h2 id="scenario-title">${e(s.title)}</h2></div><button class="icon-button" data-close aria-label="Close scenario">${icon('close')}</button></div><p>${e(s.text)}</p><h3>Discuss before your practice</h3><ul class="scenario-checks">${s.checks.map(c=>`<li>${icon('check')} ${e(c)}</li>`).join('')}</ul>${s.note?`<div class="notice">${e(s.note)}</div>`:''}<p><a href="${e(s.source)}" target="_blank" rel="noopener noreferrer">${s.source===highway?'Read the Highway Code':'Read the local source (unverified)'} ${icon('external')}</a></p><p class="small muted">This is a preparation checklist, not a manoeuvre guide or an instructor assessment.</p><button class="button primary full" id="mark-reviewed">${icon('check')} ${progress.scenarioChecks.includes(id)?'Reviewed — close':'Mark preparation reviewed'}</button>`;d.querySelector('[data-close]').onclick=()=>d.close();d.querySelector('#mark-reviewed').onclick=()=>{if(!progress.scenarioChecks.includes(id))progress.scenarioChecks.push(id);persist();d.close();render();toast('Preparation reviewed. Discuss it with your instructor.');};d.showModal();}
function download(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(progress,null,2)],{type:'application/json'}));a.download=`routewise-progress-${localDate()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function wire(){
 document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render();window.scrollTo({top:0});});
 document.querySelector('[data-action="centre"]').onclick=()=>toast('Maidstone is our first centre. Propose another in Community.');
 if(tab==='routes'){
  renderRouteList();renderDetail();
  document.querySelector('#route-search').oninput=ev=>{query=ev.target.value;renderRouteList();};
  document.querySelector('#skill-filter').onchange=ev=>{skill=ev.target.value;renderRouteList();};
  document.querySelector('#saved-only').onchange=ev=>{savedOnly=ev.target.checked;renderRouteList();};
  document.querySelector('[data-action="find-focus"]').onclick=()=>{tab='scenarios';render();};
 }
 document.querySelectorAll('[data-scenario]').forEach(b=>b.onclick=()=>scenarioDialog(b.dataset.scenario));
 document.querySelectorAll('[data-action="new-log"]').forEach(b=>b.onclick=()=>practiceDialog(selected));
 document.querySelector('[data-action="export"]')?.addEventListener('click',download);
 document.querySelector('[data-action="import"]')?.addEventListener('click',()=>document.querySelector('#import-file').click());
 document.querySelector('#import-file')?.addEventListener('change',async ev=>{const file=ev.target.files[0];if(!file)return;try{if(file.size>5e6)throw new Error('File is too large (maximum 5 MB).');const imported=validateProgress(JSON.parse(await file.text()),routes.map(r=>r.id));const ids=new Set(progress.sessions.map(s=>s.id));const merged={version:1,bookmarks:[...new Set([...progress.bookmarks,...imported.bookmarks])],scenarioChecks:[...new Set([...progress.scenarioChecks,...imported.scenarioChecks])],sessions:[...progress.sessions,...imported.sessions.filter(s=>!ids.has(s.id))]};progress=validateProgress(merged,routes.map(r=>r.id));persist();render();toast('Progress imported and merged. Existing sessions kept.');}catch(err){toast('Import failed: '+err.message);}finally{ev.target.value='';}});
 document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{if(!confirm('Delete this practice session? This cannot be undone.'))return;progress.sessions=progress.sessions.filter(s=>s.id!==b.dataset.delete);persist();render();toast('Session deleted.');});
 document.querySelector('#contribution-form')?.addEventListener('submit',ev=>{ev.preventDefault();const fields={kind:document.querySelector('#kind').value,title:document.querySelector('#proposal-title').value.trim(),roads:document.querySelector('#proposal-roads').value.trim(),notes:document.querySelector('#proposal-notes').value.trim(),evidence:document.querySelector('#proposal-evidence').value.trim()};if(!fields.title||!fields.roads||fields.notes.length<20||!fields.evidence){toast('Complete each field with useful details.');return;}const url=contributionUrl(fields);const link=document.createElement('a');link.href=url;link.target='_blank';link.rel='noopener noreferrer';link.click();});
}
try{
 const response=await fetch('./data/routes.json');if(!response.ok)throw new Error('Route data could not be loaded.');const data=await response.json();routes=data.routes;centres=data.centres;
 try{const raw=localStorage.getItem(STORAGE_KEY);if(raw)progress=validateProgress(JSON.parse(raw),routes.map(r=>r.id));}catch{storageBlocked=true;}
 render();
}catch(err){app.innerHTML=`<div class="load-error"><h1>We couldn’t load the routes.</h1><p>${e(err.message)}</p><p>Please refresh or try again later.</p></div>`;}
